from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """ Play a modified tic-tac-toe game on a 3x3 grid where each cell has a value.

    Takahashi (first player) and Aoki (second player) take turns choosing white cells.
    When a player chooses a cell, they score the points in that cell and paint it their color
    (Takahashi: red, Aoki: blue).

    The game ends when:
    - A player gets 3 consecutive cells of their color (row/column/diagonal) - that player wins
    - All cells are painted - the player with higher total score wins

    Both players play optimally. The sum of all values in the grid is guaranteed to be odd.

    Args:
        grid: A 3x3 grid of integers representing cell values

    Returns:
        "Takahashi" if Takahashi wins, "Aoki" if Aoki wins

    >>> tic_tac_toe_winner([[0, 0, 0], [0, 1, 0], [0, 0, 0]])
    'Takahashi'
    >>> tic_tac_toe_winner([[-1, 1, 0], [-4, -2, -5], [-4, -1, -5]])
    'Aoki'
    """
    takahashi_score = 0
    aoki_score = 0
    takahashi_grid = [[0] * 3 for _ in range(3)]
    aoki_grid = [[0] * 3 for _ in range(3)]

    for i in range(3):
        for j in range(3):
            if (i + j) % 2 == 0:
                takahashi_score += grid[i][j]
                takahashi_grid[i][j] = 1
            else:
                aoki_score += grid[i][j]
                aoki_grid[i][j] = 1

    # Check for Takahashi win
    for i in range(3):
        if sum(takahashi_grid[i]) == 3:
            return "Takahashi"
        if sum(takahashi_grid[j][i] for j in range(3)) == 3:
            return "Takahashi"
    if sum(takahashi_grid[i][i] for i in range(3)) == 3:
        return "Takahashi"
    if sum(takahashi_grid[i][2 - i] for i in range(3)) == 3:
        return "Takahashi"

    # Check for Aoki win
    for i in range(3):
        if sum(aoki_grid[i]) == 3:
            return "Aoki"
        if sum(aoki_grid[j][i] for j in range(3)) == 3:
            return "Aoki"
    if sum(aoki_grid[i][i] for i in range(3)) == 3:
        return "Aoki"
    if sum(aoki_grid[i][2 - i] for i in range(3)) == 3:
        return "Aoki"

    # Determine winner based on scores
    if tahashi_score > aoki_score:
        return "Takahashi"
    elif aoki_score > tahashi_score:
        return "Aoki"
    else:
        return "Aoki"
