from typing import List


def max_score(grid: List[List[int]]) -> int:
    """ Given a 2D matrix of positive integers, select one or more cells such that:
    - No two selected cells are in the same row
    - The values in the selected cells are unique

    Return the maximum sum of values you can achieve.

    Args:
        grid: A 2D list where 1 <= len(grid), len(grid[i]) <= 10 and 1 <= grid[i][j] <= 100

    >>> max_score([[1,2,3],[4,3,2],[1,1,1]])
    8
    >>> max_score([[8,7,6],[8,3,2]])
    15
    """
    rows = len(grid)
    cols = len(grid[0])
    max_sum = 0

    def solve(row, current_sum, selected_cols):
        nonlocal max_sum
        if row == rows:
            max_sum = max(max_sum, current_sum)
            return

        for col in range(cols):
            if col not in selected_cols:
                value = grid[row][col]

                valid = True
                for prev_row in range(row):
                    if prev_row < rows and col in selected_cols:
                        if grid[prev_row][col] == value:
                            valid = False
                            break

                if valid:
                    new_selected_cols = selected_cols | {col}

                    unique = True
                    values_used = []
                    for r in range(row + 1):
                        for c in new_selected_cols:
                            if r < rows and c < cols:
                                if grid[r][c] in values_used:
                                    unique = False
                                    break
                                values_used.append(grid[r][c])
                        if not unique:
                            break

                    if unique:
                        solve(row + 1, current_sum + value, new_selected_cols)

        # Skip the current row if no valid columns are found
        solve(row + 1, current_sum, selected_cols)

    solve(0, 0, set())
    return max_sum
