def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    MOD = 998244353

    def is_valid(current_grid):
        for r in range(H):
            for c in range(W):
                if current_grid[r][c] == '?':
                    continue

                # Check adjacent cells
                if r > 0 and current_grid[r-1][c] == current_grid[r][c]:
                    return False
                if r < H - 1 and current_grid[r+1][c] == current_grid[r][c]:
                    return False
                if c > 0 and current_grid[r][c-1] == current_grid[r][c]:
                    return False
                if c < W - 1 and current_grid[r][c+1] == current_grid[r][c]:
                    return False
        return True

    def solve(row, col, current_grid):
        if row == H:
            if is_valid(current_grid):
                return 1
            else:
                return 0

        if col == W:
            return solve(row + 1, 0, current_grid)

        if grid[row][col] != '?':
            return solve(row, col + 1, current_grid)

        count = 0
        for digit in ['1', '2', '3']:
            new_grid = [list(row_str) for row_str in current_grid]
            new_grid[row][col] = digit
            count = (count + solve(row, col + 1, new_grid)) % MOD
        return count

    initial_grid = [list(row_str) for row_str in grid]
    return solve(0, 0, initial_grid)
```

