    8
    >>> max_score([[8,7,6],[8,3,2]])
    15
    """
    rows = len(grid)
    cols = len(grid[0])
    max_sum = 0

    for i in range(1 << rows):
        selected_cells = []
        current_sum = 0

        for row_index in range(rows):
